import{_ as t,o as s,c as a,a2 as o}from"./chunks/framework.CQxpk36T.js";const h=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"developpement/architecture.md","filePath":"developpement/architecture.md","lastUpdated":1793563901000}'),r={name:"developpement/architecture.md"};function d(n,e,c,i,l,p){return s(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><p>TypeScript, React 19, <a href="https://r3f.docs.pmnd.rs" target="_blank" rel="noreferrer">React Three Fiber</a> (three.js), Vite, Zustand. Aucune texture à charger : tout est généré, géométrie et motifs (en GLSL).</p><h2 id="le-flux" tabindex="-1">Le flux <a class="header-anchor" href="#le-flux" aria-label="Permalink to &quot;Le flux&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>proprietes/&lt;nom&gt;/          index.ts : { propriete, site, plans, retouches }  ← alias @propriete (vite.config.ts)</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>src/model/                 types + propriété chargée, retouches appliquées : PROPERTY, site, PLANS, BOUNDS</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>src/scene/facade.ts        implantation : sections résolues, ouvertures, portes, fenêtres (LAYOUTS)</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>src/scene/*.tsx            rendu : bâtiments, façades, diorama, ciel, vie, intérieurs</span></span>
<span class="line"><span>src/ui/*.tsx               interface 2D par-dessus le canevas</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>src/ha/                    états Home Assistant (WebSocket) ou simulateur de démo</span></span></code></pre></div><p>Le moteur ne connaît aucune propriété en particulier : il lit le paquet choisi par la variable <code>PROPRIETE</code> (<code>.env.local</code>), <code>proprietes/exemple</code> par défaut. Les tests et les vérifications de la page utilisent toujours l&#39;exemple (<code>.env.test</code>, <code>.env.e2e</code>).</p><h2 id="les-dossiers" tabindex="-1">Les dossiers <a class="header-anchor" href="#les-dossiers" aria-label="Permalink to &quot;Les dossiers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Dossier</th><th>Rôle</th></tr></thead><tbody><tr><td><code>src/model/</code></td><td>Schéma de la description (<code>property.ts</code>, <code>plans.ts</code>, <code>site.ts</code>), retouches de l&#39;éditeur (<code>retouches.ts</code>) et paquet chargé (<code>loaded.ts</code>)</td></tr><tr><td><code>src/scene/</code></td><td>Scène 3D. <code>geometry.ts</code> : sections, murs percés, toitures, noues ; <code>facade.ts</code> : où percer et poser ; <code>Building</code>, <code>Facades</code>, <code>Interior</code>, <code>Diorama</code>, <code>Enclosures</code>, <code>Cars</code>, <code>Life</code>, <code>Sky</code>, <code>Solar</code> : rendu ; <code>CameraRig</code>, <code>Lighting</code> ; <code>Ghost</code> : estompage des autres bâtiments ; <code>Editor</code> : aperçus de l&#39;éditeur ; <code>windowStates</code> : fenêtres ouvertes et volets roulants d&#39;après HA ; <code>tap.ts</code> : tolérance d&#39;un toucher</td></tr><tr><td><code>src/scene/bake/</code></td><td>Éclairage précalculé (occlusion ambiante, lanternes) dans un Web Worker, gardé en IndexedDB</td></tr><tr><td><code>src/ui/</code></td><td>Barre du haut, onglets, résumé, panneau de bâtiment, éditeur, réglages, heure, météo, placement ; <code>dashboard/</code> : onglet Tableau ; <code>energy/</code> : onglet Énergie ; <code>controls.tsx</code> : commandes partagées</td></tr><tr><td><code>src/ha/</code></td><td>Connexion WebSocket à HA, simulateur de démo, état partagé (Zustand), ordres en attente</td></tr><tr><td><code>src/weather/</code>, <code>src/solar/</code></td><td>Météo en direct (Open-Meteo), production solaire</td></tr><tr><td><code>src/energy/</code></td><td>Bilan et totaux de la journée (<code>model.ts</code>, fonctions pures), simulation de la démo, historique HA, prévision Open-Meteo</td></tr><tr><td><code>src/state/</code></td><td>État de l&#39;interface (sélection, heure simulée, qualité) et brouillon de l&#39;éditeur</td></tr><tr><td><code>tools/site/</code></td><td>Terrain : cadastre IGN (Python) ou description à la main (Node)</td></tr><tr><td><code>deploy/</code></td><td>Conteneur Caddy qui sert <code>dist/</code></td></tr><tr><td><code>e2e/</code></td><td>Vérifications de la vraie page (Playwright)</td></tr><tr><td><code>scripts/media/</code></td><td>Film de démonstration et captures d&#39;écran</td></tr><tr><td><code>docs/</code></td><td>Ce site (VitePress)</td></tr></tbody></table><h2 id="home-assistant" tabindex="-1">Home Assistant <a class="header-anchor" href="#home-assistant" aria-label="Permalink to &quot;Home Assistant&quot;">​</a></h2><p><code>src/ha/connection.ts</code> ouvre la connexion avec <a href="https://github.com/home-assistant/home-assistant-js-websocket" target="_blank" rel="noreferrer">home-assistant-js-websocket</a> : connexion OAuth de Home Assistant, jetons gardés dans le navigateur, abonnement aux états et aux registres (Zones, appareils, entités). Au retour au premier plan, au retour du réseau ou à la réouverture d&#39;une page gardée en cache, un <code>ping</code> vérifie la connexion et la relance si besoin.</p><p><code>src/ha/store.ts</code> est l&#39;état partagé (Zustand) : entités, Zones, entité → Zone, et une <strong>interface commune</strong> (<code>Backend</code>) que réalisent la connexion et le simulateur de démo (<code>demo.ts</code>). Les ordres envoyés sont notés « en attente » jusqu&#39;à ce que l&#39;état de l&#39;entité change, ou six secondes : c&#39;est ce qui fait pulser les tuiles.</p><h2 id="l-editeur" tabindex="-1">L&#39;éditeur <a class="header-anchor" href="#l-editeur" aria-label="Permalink to &quot;L&#39;éditeur&quot;">​</a></h2><p>Les retouches de la page sont un brouillon (<code>src/state/editor.ts</code>, gardé dans le navigateur) ; chaque bâtiment retouché est remplacé par un aperçu de son volume pendant l&#39;édition. À l&#39;enregistrement, <code>proprietes/&lt;nom&gt;/retouches.json</code> est écrit par le serveur de développement (greffon de <code>vite.config.ts</code>) ou téléchargé. Le paquet l&#39;importe s&#39;il existe, et <code>src/model/loaded.ts</code> l&#39;applique par-dessus la description et le terrain (<code>applyRetouches</code>) : tout le reste du moteur ne voit que le résultat.</p><h2 id="conventions" tabindex="-1">Conventions <a class="header-anchor" href="#conventions" aria-label="Permalink to &quot;Conventions&quot;">​</a></h2><ul><li>Textes de l&#39;interface et commentaires en français, identifiants en anglais.</li><li>Fins de ligne LF (<code>.gitattributes</code>, <code>.editorconfig</code>).</li><li>Une propriété personnelle ne va jamais dans le dépôt : <code>proprietes/*</code> est ignoré, sauf l&#39;exemple.</li></ul>`,14)])])}const m=t(r,[["render",d]]);export{h as __pageData,m as default};
